CREATE TABLE culture_challenges(id UUID PRIMARY KEY,title VARCHAR(255) NOT NULL,description TEXT NOT NULL,type VARCHAR(40) NOT NULL,country_code VARCHAR(2),language_code VARCHAR(35),starts_at TIMESTAMPTZ NOT NULL,ends_at TIMESTAMPTZ NOT NULL,status VARCHAR(20) NOT NULL,reward_definition_id UUID,moderation_required BOOLEAN NOT NULL DEFAULT TRUE,created_by VARCHAR(100) NOT NULL,CHECK(ends_at>starts_at));CREATE INDEX idx_culture_challenges_active ON culture_challenges(status,starts_at,ends_at);CREATE INDEX idx_culture_challenges_target ON culture_challenges(country_code,language_code,status);
CREATE TABLE culture_challenge_prompts(id UUID PRIMARY KEY,challenge_id UUID NOT NULL REFERENCES culture_challenges(id) ON DELETE CASCADE,prompt TEXT NOT NULL,language_code VARCHAR(35),display_order INT NOT NULL DEFAULT 0);
CREATE TABLE culture_challenge_participants(id UUID PRIMARY KEY,challenge_id UUID NOT NULL REFERENCES culture_challenges(id),user_id VARCHAR(100) NOT NULL,joined_at TIMESTAMPTZ NOT NULL,completed_at TIMESTAMPTZ,UNIQUE(challenge_id,user_id));CREATE INDEX idx_challenge_participant_user ON culture_challenge_participants(user_id,joined_at DESC);
CREATE TABLE culture_challenge_submissions(id UUID PRIMARY KEY,user_id VARCHAR(100) NOT NULL,challenge_id UUID NOT NULL REFERENCES culture_challenges(id),post_id UUID,culture_contribution_id UUID,media_ids TEXT,language_code VARCHAR(35),translation TEXT,status VARCHAR(30) NOT NULL,moderation_reason VARCHAR(255),created_at TIMESTAMPTZ NOT NULL,withdrawn_at TIMESTAMPTZ,UNIQUE(challenge_id,user_id),CHECK(post_id IS NOT NULL OR culture_contribution_id IS NOT NULL OR media_ids IS NOT NULL));CREATE INDEX idx_challenge_submission_queue ON culture_challenge_submissions(status,created_at);
CREATE TABLE culture_consent_declarations(id UUID PRIMARY KEY,submission_id UUID NOT NULL REFERENCES culture_challenge_submissions(id),declared_by VARCHAR(100) NOT NULL,other_person_recorded BOOLEAN NOT NULL,consent_confirmed BOOLEAN NOT NULL,anonymized BOOLEAN NOT NULL,person_name VARCHAR(180),action VARCHAR(20) NOT NULL,created_at TIMESTAMPTZ NOT NULL);CREATE INDEX idx_consent_submission ON culture_consent_declarations(submission_id,created_at);
